import { MakeLogicType, afterMount, connect, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { SURVEY_PAGE_SIZE } from 'scenes/surveys/constants'
import { surveysLogic } from 'scenes/surveys/surveysLogic'
import { teamLogic } from 'scenes/teamLogic'

import { Experiment, ExperimentIdType, Survey } from '~/types'

import { surveysList } from 'products/surveys/frontend/generated/api'

export interface ExperimentFeedbackTabLogicProps {
    experiment: Experiment
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface experimentFeedbackTabLogicValues {
    currentProjectId: number | string // teamLogic
    experimentSurveys: Survey[]
    experimentSurveysLoadFailed: boolean
    experimentSurveysLoaded: boolean
    experimentSurveysLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface experimentFeedbackTabLogicActions {
    loadResponsesCount: (surveyIds: string[]) => string[] // surveysLogic
    loadExperimentSurveys: () => any
    loadExperimentSurveysFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadExperimentSurveysSuccess: (
        experimentSurveys: Survey[],
        payload?: any
    ) => {
        experimentSurveys: Survey[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface experimentFeedbackTabLogicMeta {
    key: ExperimentIdType
}

export type experimentFeedbackTabLogicType = MakeLogicType<
    experimentFeedbackTabLogicValues,
    experimentFeedbackTabLogicActions,
    ExperimentFeedbackTabLogicProps,
    experimentFeedbackTabLogicMeta
>

export const experimentFeedbackTabLogic = kea<experimentFeedbackTabLogicType>([
    props({} as ExperimentFeedbackTabLogicProps),
    key((props) => props.experiment.id),
    path((key) => ['scenes', 'experiments', 'experimentFeedbackTabLogic', key]),
    connect(() => ({
        values: [teamLogic, ['currentProjectId']],
        actions: [surveysLogic, ['loadResponsesCount']],
    })),
    loaders(({ props, values }) => ({
        experimentSurveys: {
            __default: [] as Survey[],
            loadExperimentSurveys: async () => {
                const linkedFlagId = props.experiment.feature_flag?.id
                if (!linkedFlagId) {
                    return []
                }
                const response = await surveysList(String(values.currentProjectId), {
                    linked_flag_id: linkedFlagId,
                    archived: false,
                    limit: SURVEY_PAGE_SIZE,
                })
                // The surveys scene components this tab reuses are typed on the handwritten Survey type,
                // which declares the linked flag's filters more strictly than the generated type does
                return (response.results ?? []) as unknown as Survey[]
            },
        },
    })),
    reducers({
        experimentSurveysLoaded: [
            false,
            {
                loadExperimentSurveysSuccess: () => true,
                loadExperimentSurveysFailure: () => true,
            },
        ],
        experimentSurveysLoadFailed: [
            false,
            {
                loadExperimentSurveys: () => false,
                loadExperimentSurveysFailure: () => true,
            },
        ],
    }),
    listeners(({ actions }) => ({
        loadExperimentSurveysSuccess: ({ experimentSurveys }) => {
            if (experimentSurveys.length > 0) {
                actions.loadResponsesCount(experimentSurveys.map((survey) => survey.id))
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadExperimentSurveys()
    }),
])
